// #617 P4 criterion L — a hosted source's sandbox installs a closed
// dependency tree: committed lockfiles, installed with `npm ci`.
//
// Before P4 the sandbox ran `npm install` in two directories from two written
// `package.json` files. The pin and the bridge's two packages were exact, but
// everything under them resolved afresh at each creation, so two sandboxes of
// one pin could run different code. The fix: one lockfile for the pin and one
// for the bridge, generated by `scripts/generate-hosted-lockfiles.ts` (a pin
// move re-runs it), written beside each `package.json`, and installed with
// `npm ci --ignore-scripts`, which installs exactly the lockfile's tree or
// fails.
//
// WHAT IS ASSERTED, over what the install step writes (`hostedInstallPlan`),
// for every hosted entry of the manifest:
//   - each directory is installed with `npm ci --ignore-scripts`, never
//     `npm install`;
//   - each directory is written a `package.json` and a `package-lock.json`
//     that agree the way `npm ci` requires (the lockfile's root names the
//     same package and the same dependencies);
//   - the pin's lockfile roots at exactly the manifest's pin, and the
//     bridge's at exactly `BRIDGE_PACKAGES`, each installed at that version —
//     so a pin moved without re-running the script fails here;
//   - every package entry carries an `integrity` and resolves from the one
//     registry the sandbox may reach while it installs;
//   - every dependency edge in each tree resolves to an entry of the same
//     lockfile (the tree is closed: `npm ci` has nothing to look up);
//   - the script exists and the deploy guide's pin-move procedure names it.
//
// WHAT IT CANNOT SHOW: that `npm ci` inside a real sandbox installs this tree
// and the source then answers. That is measured live, against a sandbox, and
// recorded in the phase record with one `npm ls --all --json` read.
//
// Run with: npm test
//   (or: node --test --experimental-strip-types src/lib/mcp/hosting/lockfiles.test.ts)

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CIVIC_MANIFEST } from '@typedstandards/civic-typed-router';
import { BRIDGE_PACKAGES } from './bridge-source.ts';
import { PACKAGE_REGISTRY_HOSTS, hostedInstallPlan, type HostedInstallDir } from './lifecycle.ts';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..');
const SCRIPT = 'scripts/generate-hosted-lockfiles.ts';

interface LockEntry {
  version?: string;
  resolved?: string;
  integrity?: string;
  link?: boolean;
  dependencies?: Record<string, string>;
  peerDependencies?: Record<string, string>;
  peerDependenciesMeta?: Record<string, { optional?: boolean }>;
}
interface Lockfile {
  name: string;
  lockfileVersion: number;
  packages: Record<string, LockEntry & { name?: string }>;
}

// Router 0.4.0 (#632 D11): every npm-package variant of every entry, as the
// lockfile script writes one per variant.
const HOSTED = CIVIC_MANIFEST.flatMap((entry) =>
  entry.hostings.flatMap((variant) => (variant.kind === 'npm-package' ? [{ entry, hosting: variant }] : [])),
);

function fileIn(step: HostedInstallDir, name: string): string | undefined {
  return step.files.find((file) => file.path === `${step.dir}/${name}`)?.content;
}

function lockfileOf(step: HostedInstallDir): Lockfile {
  const text = fileIn(step, 'package-lock.json');
  assert.ok(text, `${step.dir}: no package-lock.json is written beside its package.json`);
  return JSON.parse(text!) as Lockfile;
}

function packageJsonOf(step: HostedInstallDir): { name: string; dependencies: Record<string, string> } {
  const text = fileIn(step, 'package.json');
  assert.ok(text, `${step.dir}: no package.json is written`);
  return JSON.parse(text!);
}

/** Where npm finds `dep` for the package installed at `from`: its own
 *  node_modules, then each enclosing one, then the root's. */
function resolveEdge(lock: Lockfile, from: string, dep: string): string | undefined {
  let base = from;
  for (;;) {
    const candidate = base === '' ? `node_modules/${dep}` : `${base}/node_modules/${dep}`;
    if (lock.packages[candidate]) return candidate;
    if (base === '') return undefined;
    const at = base.lastIndexOf('/node_modules/');
    base = at === -1 ? '' : base.slice(0, at);
  }
}

test('premise: the manifest has a hosted entry, so the assertions below have something to read', () => {
  assert.ok(HOSTED.length > 0, 'no manifest entry carries an npm-package hosting variant');
});

for (const { hosting } of HOSTED) {
  const plan = hostedInstallPlan(hosting);
  const [pin, bridge] = plan;
  const label = `${hosting.package}@${hosting.version}`;

  test(`${label}: the install step fills two directories, the pin's and the bridge's`, () => {
    assert.equal(plan.length, 2);
    assert.deepEqual(packageJsonOf(pin).dependencies, { [hosting.package]: hosting.version });
    assert.deepEqual(packageJsonOf(bridge).dependencies, BRIDGE_PACKAGES);
  });

  test(`${label}: each directory is installed with npm ci --ignore-scripts, never npm install`, () => {
    for (const step of plan) {
      assert.equal(step.npmArgs[0], 'ci', `${step.dir} runs \`npm ${step.npmArgs.join(' ')}\`: the tree resolves at each creation`);
      assert.ok(step.npmArgs.includes('--ignore-scripts'), `${step.dir}: install scripts are allowed to run`);
    }
  });

  test(`${label}: each package.json and its package-lock.json agree, as npm ci requires`, () => {
    for (const step of plan) {
      const pkg = packageJsonOf(step);
      const lock = lockfileOf(step);
      assert.equal(lock.lockfileVersion, 3, `${step.dir}: lockfileVersion`);
      assert.equal(lock.name, pkg.name, `${step.dir}: the lockfile names another package`);
      assert.equal(lock.packages['']?.name, pkg.name, `${step.dir}: the lockfile's root names another package`);
      assert.deepEqual(lock.packages[''].dependencies, pkg.dependencies, `${step.dir}: the lockfile's root dependencies are not the package.json's`);
    }
  });

  test(`${label}: the pin's lockfile roots at exactly the manifest's pin, the bridge's at exactly BRIDGE_PACKAGES`, () => {
    const pinLock = lockfileOf(pin);
    assert.deepEqual(pinLock.packages[''].dependencies, { [hosting.package]: hosting.version }, 'the pin moved without re-running ' + SCRIPT);
    assert.equal(pinLock.packages[`node_modules/${hosting.package}`]?.version, hosting.version, `the lockfile installs another version of ${hosting.package}`);
    const bridgeLock = lockfileOf(bridge);
    assert.deepEqual(bridgeLock.packages[''].dependencies, { ...BRIDGE_PACKAGES }, 'BRIDGE_PACKAGES moved without re-running ' + SCRIPT);
    for (const [name, version] of Object.entries(BRIDGE_PACKAGES)) {
      assert.equal(bridgeLock.packages[`node_modules/${name}`]?.version, version, `the lockfile installs another version of ${name}`);
    }
  });

  test(`${label}: every package entry carries an integrity and resolves from the registry the sandbox may reach`, () => {
    const allowed = PACKAGE_REGISTRY_HOSTS.map((host) => `https://${host}/`);
    for (const step of plan) {
      const lock = lockfileOf(step);
      const entries = Object.entries(lock.packages).filter(([key]) => key !== '');
      assert.ok(entries.length > 0, `${step.dir}: the lockfile holds no package`);
      for (const [key, value] of entries) {
        assert.notEqual(value.link, true, `${step.dir}: ${key} is a link, not a registry package`);
        assert.match(value.integrity ?? '', /^sha512-[A-Za-z0-9+/]+=*$/, `${step.dir}: ${key} has no sha512 integrity`);
        assert.ok(allowed.some((prefix) => value.resolved?.startsWith(prefix)), `${step.dir}: ${key} resolves from ${value.resolved}, which the sandbox cannot reach`);
      }
    }
  });

  test(`${label}: every dependency edge in each tree resolves inside the same lockfile`, () => {
    for (const step of plan) {
      const lock = lockfileOf(step);
      for (const [key, value] of Object.entries(lock.packages)) {
        const required = {
          ...value.dependencies,
          ...Object.fromEntries(Object.entries(value.peerDependencies ?? {}).filter(([dep]) => !value.peerDependenciesMeta?.[dep]?.optional)),
        };
        for (const dep of Object.keys(required)) {
          assert.ok(resolveEdge(lock, key, dep), `${step.dir}: ${key || '(root)'} needs ${dep}, which the lockfile does not hold`);
        }
      }
    }
  });
}

test('the lockfiles come from a script in the repository, and the guide\'s pin-move procedure names it', () => {
  assert.ok(existsSync(path.join(REPO, SCRIPT)), `${SCRIPT} does not exist`);
  const guide = readFileSync(path.join(REPO, 'docs/deploy.md'), 'utf8');
  assert.ok(guide.includes(SCRIPT), `docs/deploy.md does not name ${SCRIPT}`);
});
